export const clamp=(n,min,max)=>Math.min(max,Math.max(min,n));
export const clock=s=>`${Math.floor(Math.max(0,s)/60).toString().padStart(2,'0')}:${Math.floor(Math.max(0,s)%60).toString().padStart(2,'0')}`;
export function suspicionStep(state,looking,dt,{temper=0,gentle=false}={}){dt=clamp(dt,0,.5);if(looking===null)return{value:clamp(state.value-dt*55,0,100),stare:0};const stare=looking?state.stare+dt:0,speed=(1+clamp(temper,0,60)/400)*(gentle?.6:1);const value=looking?(stare>1?clamp(state.value+dt*25*speed,0,100):state.value):clamp(state.value-dt*55,0,100);return{stare,value};}
export function rankFor(rp){const names=['0','E','D','C','B','A','Elite'],level=Math.min(6,Math.floor(Math.max(0,rp)/150));return{label:names[level],level,within:Math.max(0,rp)%150,next:names[Math.min(6,level+1)]};}
export function weekKey(date=new Date()){const d=new Date(date);d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return`${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`;}
export function settle(profile,s,completed){const perfect=completed&&!s.warnings&&!s.escapes&&!s.pauses,delta=completed?20+(perfect?10:0):-10,week=weekKey(),count=profile.week===week?profile.weekCount:0,bonus=completed&&count===4?2:0;return{...profile,rp:Math.max(0,profile.rp+delta),credits:profile.credits+(completed?1:0)+bonus,temper:clamp(profile.temper+(completed?-10:15),0,60),week,weekCount:count+(completed?1:0),history:[{id:s.id,task:s.task,seconds:completed?s.total:Math.max(0,s.total-s.remaining),completed,perfect,mode:s.mode,warnings:s.warnings,escapes:s.escapes,date:new Date().toISOString(),rp:delta,bonus},...profile.history].slice(0,200)};}
